/**
 * stars.js — Bright star catalog for SkyMap Cast Receiver
 * ════════════════════════════════════════════════════════
 *
 * STAR_CATALOG: Array of [name, raDeg, decDeg, magnitude, bvIndex]
 *   name     — common name (or Bayer designation)
 *   raDeg    — Right Ascension in decimal degrees (J2000)
 *   decDeg   — Declination in decimal degrees (J2000)
 *   magnitude — visual magnitude
 *   bvIndex  — B–V colour index (negative = blue, positive = red/orange)
 *
 * Source: hygdata_v42.csv — the same asset the phone app ships, already
 * trimmed to mag ≤ 6.5 (naked-eye limit). 8870 stars: matches
 * the app's star field instead of a hand-picked bright subset.
 *
 * Regenerate with: python3 tools/generate_cast_star_catalog.py
 *
 * Helper functions:
 *   bvToColor(bv)    → { r, g, b }  (values 0–1, for Three.js BufferAttribute)
 *   magToSize(mag)   → pixels       (for gl_PointSize)
 */

